var t=`1407-oka-ia`;var a=`world-1407`;var n=`WS`;var l=`oceania`;var o=4;var s=40;var c={en:`Oka i'a`,ua:`Ока іа`};var m={en:`Samoan oka i’a: chilled coconut-lime fish salad. Unlike the classic raw fish dish, this variation uses safely cooked fish.`,ua:`Самоанський ока іа: холодний салат із риби, лайма й кокосу. На відміну від традиційної страви із сирою рибою, тут рибу повністю готують.`};var u=[{en:`Steam fish fillets until they reach 63°C at the centre, about 10–12 minutes, then promptly chill.`,ua:`Готуйте рибне філе на парі до 63°C у центрі приблизно 10–12 хвилин, тоді швидко охолодіть.`,t:[`steaming`],m:12,i:[[`red-snapper`,600,`g`]]},{en:`Cut the chilled fish into bite-size cubes and coat with lime juice. Refrigerate for 10 minutes.`,ua:`Наріжте охолоджену рибу невеликими кубиками та полийте соком лайма. Поставте в холодильник на 10 хвилин.`,t:[`dicing`,`acid-marination`],m:10,i:[[`lime-juice`,100,`ml`]]},{en:`Dice tomato and cucumber; thinly slice red onion and chop chili. Fold into the fish.`,ua:`Наріжте кубиками помідори та огірок, тонко нашаткуйте червону цибулю й подрібніть чилі. Обережно змішайте з рибою.`,t:[`dicing`,`mixing`],m:8,i:[[`tomato`,180,`g`],[`cucumber`,150,`g`],[`red-onion`,80,`g`],[`bird-s-eye-chili`,1,`pcs`]]},{en:`Fold in coconut milk and salt. Chill briefly and serve in small bowls.`,ua:`Вмішайте кокосове молоко й сіль. Ненадовго охолодіть і подавайте в невеликих мисках.`,t:[`folding-in`],m:10,i:[[`coconut-milk`,250,`ml`],[`sea-salt`,4,`g`]]}];var h={slug:t,id:a,country:`WS`,region:l,servings:4,minutes:40,title:c,text:m,steps:u};export{n as country,h as default,a as id,s as minutes,l as region,o as servings,t as slug,u as steps,m as text,c as title};